function assertFileExists(targetPath: string) {
  if (!fs.existsSync(targetPath)) {
    throw new Error(`File not found: ${targetPath}`);
  }
}

function parseThresholds(thresholdStrings?: string[]): { thresholds: Record<string, number> | null; error?: string } {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return { thresholds: null };
  }

  const thresholds: Record<string, number> = {};

  for (const threshStr of thresholdStrings) {
    const parts = threshStr.split('=');
    if (parts.length !== 2) {
      return { error: `Malformed threshold "${threshStr}": expected format <metric>=<number>` };
    }

    const metricId = parts[0].trim();
    const minStr = parts[1].trim();

    if (!metricId) {
      return { error: `Malformed threshold "${threshStr}": metric id is empty` };
    }

    const min = Number(minStr);
    if (isNaN(min)) {
      return { error: `Malformed threshold "${threshStr}": minimum must be a number` };
    }

    if (min < 0 || min > 1) {
      return { error: `Malformed threshold "${threshStr}": minimum must be between 0 and 1` };
    }

    thresholds[metricId] = min;
  }

  return { thresholds };
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  const thresholdParse = parseThresholds(options.threshold);
  if (thresholdParse.error) {
    log.error(thresholdParse.error);
    const validMetrics = ['exact_match', 'toxicity', 'length_variance'];
    console.error(`Valid metric IDs: ${validMetrics.join(', ')}`);
    process.exit(2);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  const unknownMetrics = thresholdParse.thresholds ? Object.keys(thresholdParse.thresholds).filter(
    (metricId) => !evaluations.find((m: any) => m.id === metricId)
  ) : [];

  if (unknownMetrics.length > 0) {
    const validMetrics = evaluations.map((m: any) => m.id);
    log.error(`Unknown metric ID: ${unknownMetrics.join(', ')}`);
    console.error(`Valid metric IDs: ${validMetrics.join(', ')}`);
    process.exit(2);
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: thresholdParse.thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({

